def get_gad7_band(score):
    if pd.isna(score):
        return np.nan
    if score <= 4:
        return 'minimal'
    elif score <= 9:
        return 'mild'
    elif score <= 14:
        return 'moderate'
    else:
        return 'severe'

def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    for it in items:
        v = row[it]
        if v not in [0, 1, 2, 3]:
            vals.append(-9)
        else:
            vals.append(v)

    valid_vals = [v for v in vals if v in [0, 1, 2, 3]]
    n_answered = len(valid_vals)
    n_missing = 9 - n_answered

    if n_missing >= 2:
        total = np.nan
        prorated = np.nan
    elif n_missing == 1:
        # scale up: sum * 9 / 8, round half up
        s = sum(valid_vals)
        raw_scaled = (s * 9) / 8
        # half rounding up: decimal >= 0.5 rounds up
        # np.floor(x + 0.5) or decimal round? Let's check Python's round or decimal.
        # Python 3 round rounds to even. Let's write a robust half-up helper.
        from decimal import Decimal, ROUND_HALF_UP
        total = float(Decimal(str(raw_scaled)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = float(sum(valid_vals))
        prorated = False

    # self harm flag
    q9 = row['phq9_9']
    if q9 not in [0, 1, 2, 3]:
        sh_flag = np.nan
    else:
        sh_flag = True if q9 > 0 else False

    band = get_phq9_band(total)
    return pd.Series({
        'phq9_total': total,
        'phq9_band': band,
        'phq9_prorated': prorated,
        'phq9_self_harm_flag': sh_flag
    })

