    if n_missing >= 2:
        total = np.nan
        prorated = np.nan
    elif n_missing == 1:
        s = sum(valid_vals)
        raw_scaled = (s * 7) / 6
        from decimal import Decimal, ROUND_HALF_UP
        total = float(Decimal(str(raw_scaled)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = float(sum(valid_vals))
        prorated = False

